import { z } from 'zod';

// ---------------------------------------------------------------------------
// Identifiers and timestamps
// ---------------------------------------------------------------------------

/** Ids of rows we own (project, task, activity): uuidv7 generated by Postgres 18. */
export const RowId = z.uuid();

/** Ids of Better Auth rows (user, organization, apikey, invitation). @pm/db stores them as uuid. */
export const AuthId = z.uuid();

export const UserId = AuthId;
export const WorkspaceId = AuthId;
export const ProjectId = RowId;
export const TaskId = RowId;

/**
 * Timestamps travel as ISO 8601 UTC strings. Servers may hand in a Date (what Drizzle returns);
 * parsing normalises both forms to `2026-10-22T18:19:06.997Z`.
 */
export const Timestamp = z
  .union([z.date(), z.iso.datetime({ offset: true })])
  .transform((value) => (value instanceof Date ? value : new Date(value)).toISOString())
  .pipe(z.iso.datetime());

// ---------------------------------------------------------------------------
// Status
// ---------------------------------------------------------------------------

export const TASK_STATUSES = ['backlog', 'todo', 'in_progress', 'in_review', 'done', 'canceled'] as const;
export const TaskStatus = z.enum(TASK_STATUSES);
export type TaskStatus = z.infer<typeof TaskStatus>;

export const TASK_STATUS_LABELS: Record<TaskStatus, string> = {
  backlog: 'Backlog',
  todo: 'Todo',
  in_progress: 'In progress',
  in_review: 'In review',
  done: 'Done',
  canceled: 'Canceled',
};

/** Statuses that count as open work (project counts, rail badges). */
export const OPEN_TASK_STATUSES = ['backlog', 'todo', 'in_progress', 'in_review'] as const;
export const OpenTaskStatus = z.enum(OPEN_TASK_STATUSES);
export type OpenTaskStatus = z.infer<typeof OpenTaskStatus>;

export function isOpenStatus(status: TaskStatus): status is OpenTaskStatus {
  return (OPEN_TASK_STATUSES as readonly string[]).includes(status);
}

// ---------------------------------------------------------------------------
// Priority
// ---------------------------------------------------------------------------

/** Ordered from lowest to highest. The index is the smallint stored in the database. */
export const PRIORITIES = ['none', 'low', 'medium', 'high', 'urgent'] as const;
export const Priority = z.enum(PRIORITIES);
export type Priority = z.infer<typeof Priority>;

export const PRIORITY_LABELS: Record<Priority, string> = {
  none: 'No priority',
  low: 'Low',
  medium: 'Medium',
  high: 'High',
  urgent: 'Urgent',
};

/** Database value (0 to 4) for a priority. */
export function priorityToValue(priority: Priority): number {
  return PRIORITIES.indexOf(priority);
}

/** Priority for a database value; throws on anything outside 0 to 4. */
export function priorityFromValue(value: number): Priority {
  const priority = PRIORITIES[value];
  if (priority === undefined) throw new RangeError(`Invalid priority value: ${value}`);
  return priority;
}

// ---------------------------------------------------------------------------
// People and agents
// ---------------------------------------------------------------------------

export const UserKind = z.enum(['person', 'agent']);
export type UserKind = z.infer<typeof UserKind>;

/** Workspace roles from the Better Auth organization plugin. owner and admin count as admin. */
export const WorkspaceRole = z.enum(['owner', 'admin', 'member']);
export type WorkspaceRole = z.infer<typeof WorkspaceRole>;

export function isAdminRole(role: WorkspaceRole): boolean {
  return role === 'owner' || role === 'admin';
}

export const ApiKeyAccess = z.enum(['read', 'write']);
export type ApiKeyAccess = z.infer<typeof ApiKeyAccess>;

// ---------------------------------------------------------------------------
// Project keys
// ---------------------------------------------------------------------------

export const PROJECT_KEY_PATTERN = /^[A-Z][A-Z0-9]{1,5}$/;
const PROJECT_KEY_MESSAGE = 'Use 2 to 6 letters or digits, starting with a letter';

/** Canonical project key, e.g. PAY. Strict: no case folding. Use for outputs and stored values. */
export const ProjectKey = z.string().regex(PROJECT_KEY_PATTERN, PROJECT_KEY_MESSAGE);
export type ProjectKey = z.infer<typeof ProjectKey>;

/** Project key as typed by a person or agent: trimmed and upper-cased before validation. */
export const ProjectKeyInput = z
  .string()
  .trim()
  .toUpperCase()
  .regex(PROJECT_KEY_PATTERN, PROJECT_KEY_MESSAGE);

/**
 * Suggests a key from a project name, as in the New project dialog: the first three letters or
 * digits of the first word that starts with a letter ("Billing reconciliation" gives "BIL").
 * Short first words borrow from the next ones. Returns null when nothing valid can be built.
 */
export function suggestProjectKey(name: string): string | null {
  const words = name
    .normalize('NFKD')
    .replace(/[^A-Za-z0-9\s]/g, '')
    .toUpperCase()
    .split(/\s+/)
    .filter(Boolean);
  const first = words.findIndex((word) => /^[A-Z]/.test(word));
  if (first === -1) return null;
  const candidate = words.slice(first).join('').slice(0, 3);
  return PROJECT_KEY_PATTERN.test(candidate) ? candidate : null;
}

// ---------------------------------------------------------------------------
// Task keys
// ---------------------------------------------------------------------------

/** Largest task number: Postgres integer range. */
export const MAX_TASK_NUMBER = 2_147_483_647;

export const TASK_KEY_PATTERN = /^([A-Z][A-Z0-9]{1,5})-([1-9][0-9]{0,9})$/;
const TASK_KEY_MESSAGE = 'Use a task key like PAY-142';

export interface TaskKeyParts {
  projectKey: string;
  number: number;
}

function splitTaskKey(value: string): TaskKeyParts | null {
  const match = TASK_KEY_PATTERN.exec(value);
  if (!match) return null;
  const number = Number(match[2]);
  if (!Number.isSafeInteger(number) || number > MAX_TASK_NUMBER) return null;
  return { projectKey: match[1] as string, number };
}

/** Canonical task key, e.g. PAY-142. Strict: no case folding. Use for outputs. */
export const TaskKey = z
  .string()
  .regex(TASK_KEY_PATTERN, TASK_KEY_MESSAGE)
  .refine((value) => splitTaskKey(value) !== null, { message: 'Task number is out of range' });
export type TaskKey = z.infer<typeof TaskKey>;

/** Task key as typed: trimmed and upper-cased before validation, so `pay-142` is accepted. */
export const TaskKeyInput = z
  .string()
  .trim()
  .toUpperCase()
  .regex(TASK_KEY_PATTERN, TASK_KEY_MESSAGE)
  .refine((value) => splitTaskKey(value) !== null, { message: 'Task number is out of range' });

/** Parses a task key (any case, surrounding spaces allowed) into its parts. */
export const TaskKeyParts = TaskKeyInput.transform((value) => splitTaskKey(value) as TaskKeyParts);

/** Parses `PAY-142` into `{ projectKey: 'PAY', number: 142 }`. Throws a ZodError on invalid input. */
export function parseTaskKey(value: string): TaskKeyParts {
  return TaskKeyParts.parse(value);
}

/** Like parseTaskKey but returns null instead of throwing. */
export function safeParseTaskKey(value: string): TaskKeyParts | null {
  const result = TaskKeyParts.safeParse(value);
  return result.success ? result.data : null;
}

export function formatTaskKey(projectKey: string, number: number): string {
  return `${projectKey}-${number}`;
}
